(function(){
let definitions,records=[],departments=[],type=2,current=null,filterDate='',historyOrigin=false;
const safe=value=>esc(String(value??''));
const bilingual=(zh,vi)=>`<span class="fire-zh">${zh}</span><small class="fire-vi">${vi}</small>`;
const statusText=value=>value==='confirmed'?'已確認 / Đã xác nhận':value==='submitted'?'待防火管理人確認 / Chờ xác nhận':'草稿 / Bản nháp';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const deptName=id=>{const d=departments.find(x=>x.id===id);return d?d.name_zh||d.name_vi||d.name_en||'':'';};
const manager=()=>['admin','supervisor'].includes(profile?.role);
window.fireFormTabs=selected=>`<nav class="fire-form-tabs" aria-label="消防檢查表附件"><button type="button" data-fire-form-tab="1" class="${selected===1?'active':''}">附件 1　日常火源自行檢查表</button><button type="button" data-fire-form-tab="2" class="${selected===2?'active':''}">附件 2　防火避難設施自行檢查表</button><button type="button" data-fire-form-tab="3" class="${selected===3?'active':''}">附件 3　消防安全設備自行檢查紀錄表</button><button type="button" data-fire-form-tab="4" class="${selected===4?'active':''}">簽核紀錄 / Lịch sử xác nhận</button></nav>`;
window.bindFireFormTabs=()=>document.querySelectorAll('[data-fire-form-tab]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.fireFormTab);if(n===1)window.renderFireDaily();else if(n===4)window.renderFireApprovalHistory();else window.renderFireAttachments(n);});
async function load(){
 if(!definitions){const res=await fetch('/fire-attachments-data.json?v=86');if(!res.ok)throw Error('form_definition_unavailable');definitions=await res.json();}
 const result=await api({action:'fire_attachment_list',form_type:type});records=result.records||[];departments=result.departments||[];
}
function blank(){return {id:crypto.randomUUID(),form_type:type,inspection_date:today(),department_id:departments.find(d=>d.id===profile?.department_id)?.id||departments[0]?.id||'',responsible_area:'',implementer_name:localStorage.getItem('inspection_operator_name')||'',entries:Array.from({length:9},(_,i)=>({item:i+1,status:'',note:''})),situation_report:'',manager_name:'',manager_disposition:'',manager_signature:'',owner_disposition:'',owner_signature:'',status:'draft',updated_at:null};}
function list(){const title=definitions[String(type)];$('#content').innerHTML=window.fireFormTabs(type)+`<p class="fire-intro">${safe(title.titleVi)}</p><div class="filter-row"><label>實施日期 / Ngày thực hiện<input id="fireAttachmentDateFilter" type="date" class="select" value="${safe(filterDate)}"></label><button id="fireAttachmentNew" class="btn primary">新增附件 ${type} / Tạo mới</button></div><div class="table-wrap"><table class="matrix"><thead><tr><th>實施日期</th><th>部門</th><th>負責區域</th><th>實施人員</th><th>狀態</th><th>操作</th></tr></thead><tbody>${records.filter(r=>!filterDate||r.inspection_date===filterDate).map(r=>`<tr><td>${safe(r.inspection_date)}</td><td>${safe(deptName(r.department_id))}</td><td>${safe(r.responsible_area)}</td><td>${safe(r.implementer_name)}</td><td>${statusText(r.status)}</td><td><button class="btn secondary" data-attachment-open="${safe(r.id)}">${r.status==='submitted'&&manager()?'防火管理人確認':'檢視／修改'}</button></td></tr>`).join('')}</tbody></table></div>`;window.bindFireFormTabs();$('#fireAttachmentDateFilter').onchange=e=>{filterDate=e.target.value;list();};$('#fireAttachmentNew').onclick=()=>{current=blank();editor();};document.querySelectorAll('[data-attachment-open]').forEach(b=>b.onclick=()=>{current=structuredClone(records.find(r=>r.id===b.dataset.attachmentOpen));editor();});}
function selector(index,item,locked){return `<select data-attachment-status="${index}" aria-label="第${index+1}項檢查結果" ${locked?'disabled':''}><option value="" ${!item.status?'selected':''}>—</option>${[['O','Ｏ 符合'],['V','Ｖ 已改善'],['X','Ｘ 異常'],['NA','不適用']].map(([v,t])=>`<option value="${v}" ${item.status===v?'selected':''}>${t}</option>`).join('')}</select>`;}
function editor(){const r=current,def=definitions[String(type)],locked=r.status!=='draft';const rows=def.items.map((item,i)=>`<tr><td class="fire-attachment-number">${i+1}</td>${type===3?`<td class="fire-attachment-equipment">${safe(item.name).replaceAll('\n','<br>')}</td>`:''}<td class="fire-attachment-criterion">${safe(item.text)}</td><td>${selector(i,r.entries[i]||{},locked)}</td><td><textarea data-attachment-note="${i}" rows="2" maxlength="1000" ${locked?'disabled':''}>${safe(r.entries[i]?.note)}</textarea></td></tr>`).join('');
 $('#content').innerHTML=window.fireFormTabs(type)+`<section class="fire-form fire-sheet fire-attachment-sheet"><div class="filter-row"><button id="fireAttachmentBack" class="btn secondary">返回清單</button>${!locked?'<button id="fireAttachmentQuick" class="btn secondary">一鍵填入符合 Ｏ</button>':''}<span class="tag ${r.status==='confirmed'?'normal':r.status==='submitted'?'pending':'none'}">${statusText(r.status)}</span></div><header class="fire-document-heading"><span class="fire-appendix">附件 ${type}<small>Phụ lục ${type}</small></span><div class="fire-document-title"><strong>${safe(def.titleZh)}</strong><small>${safe(def.titleVi)}</small></div></header><div class="fire-fields"><label>${bilingual('實施人員','Nhân viên thực hiện')}<input id="fireAttachmentImplementer" class="select" maxlength="100" value="${safe(r.implementer_name)}" ${locked?'disabled':''}></label><label>${bilingual('負責區域','Khu vực phụ trách')}<input id="fireAttachmentArea" class="select" maxlength="200" value="${safe(r.responsible_area)}" ${locked?'disabled':''}></label><label>${bilingual('實施日期','Ngày thực hiện')}<input id="fireAttachmentDate" class="select" type="date" value="${safe(r.inspection_date)}" max="${today()}" ${locked?'disabled':''}></label><label>${bilingual('部門','Bộ phận')}<select id="fireAttachmentDept" class="select" ${locked?'disabled':''}>${departments.map(d=>`<option value="${safe(d.id)}" ${d.id===r.department_id?'selected':''}>${safe(deptName(d.id))}</option>`).join('')}</select></label></div><div class="table-wrap fire-grid"><table class="matrix"><thead><tr><th>項次<br>STT</th>${type===3?`<th>${bilingual('設備內容','Nội dung thiết bị')}</th>`:''}<th>${bilingual('檢查重點','Nội dung kiểm tra trọng điểm')}</th><th>${bilingual(type===2?'檢查狀況':'檢查結果','Kết quả kiểm tra')}</th><th>${bilingual('處置／註記','Tình hình xử lý / Ghi chú')}</th></tr></thead><tbody>${rows}</tbody></table></div>${type===2?`<label class="fire-attachment-report">${bilingual('狀況回報','Báo cáo tình trạng')}<textarea id="fireAttachmentReport" rows="3" maxlength="2000" ${locked?'disabled':''}>${safe(r.situation_report)}</textarea></label>`:''}<div class="fire-attachment-signoffs"><section><h3>${bilingual('防火管理人處置情形暨簽章','Tình hình xử lý và ký xác nhận của người quản lý PCCC')}</h3><div id="fireAttachmentManager"></div></section><section><h3>${bilingual('管理權人處置情形暨簽章','Tình hình xử lý và ký xác nhận của người có thẩm quyền quản lý')}</h3><div id="fireAttachmentOwner"></div></section></div><div class="fire-legend">符號說明：Ｏ 符合規定；Ｖ 立即改善後符合規定；Ｘ 無法使用、損壞或無法立即改善；不適用＝本場所無此設備。<br>Giải thích ký hiệu: O Phù hợp; V Phù hợp sau khi khắc phục; X Hư hỏng hoặc không thể khắc phục ngay; Không áp dụng = Không có thiết bị này.</div><div class="fire-notice">備考：如有異常現象，應立即報告防火管理人。<br>Ghi chú: Nếu phát hiện bất thường, phải lập tức báo cáo cho người quản lý PCCC.</div>${!locked?`<div class="fire-actions"><button id="fireAttachmentDraft" class="btn secondary">儲存草稿</button><button id="fireAttachmentSubmit" class="btn primary">送交防火管理人</button></div>`:''}${r.status==='submitted'&&manager()?`<div class="fire-actions"><button id="fireAttachmentConfirm" class="btn primary">確認完成並簽章</button><button id="fireAttachmentReturn" class="btn danger">退回補正</button></div>`:''}</section>`;
 window.bindFireFormTabs();$('#fireAttachmentBack').onclick=()=>historyOrigin?window.renderFireApprovalHistory():list();
 const mgr=$('#fireAttachmentManager'),owner=$('#fireAttachmentOwner');
 if(r.status==='submitted'&&manager()){
  mgr.innerHTML=`<label>防火管理人姓名<input id="fireAttachmentManagerName" maxlength="100" value="${safe(r.manager_name)}"></label><label>處置情形<textarea id="fireAttachmentDisposition" maxlength="2000" rows="3">${safe(r.manager_disposition)}</textarea></label><label>簽章／簽名<input id="fireAttachmentSignature" maxlength="100" value="${safe(r.manager_signature)}"></label>`;
  owner.innerHTML=`<p>${safe(r.owner_disposition)}　${safe(r.owner_signature)}</p>`;
  $('#fireAttachmentConfirm').onclick=()=>review('confirm');$('#fireAttachmentReturn').onclick=()=>review('return');
 }else{mgr.innerHTML=`<p>${safe(r.manager_name)}　${safe(r.manager_disposition)}　${safe(r.manager_signature)}</p>`;owner.innerHTML=`<p>${safe(r.owner_disposition)}　${safe(r.owner_signature)}</p>`;}
 if(!locked){$('#fireAttachmentQuick').onclick=()=>{document.querySelectorAll('[data-attachment-status]').forEach(el=>{if(!el.value)el.value='O';});};$('#fireAttachmentDraft').onclick=()=>save('draft');$('#fireAttachmentSubmit').onclick=()=>save('submitted');}
}
async function save(status){const r=current;const entries=[...document.querySelectorAll('[data-attachment-status]')].map((el,i)=>({item:i+1,status:el.value,note:document.querySelector(`[data-attachment-note="${i}"]`).value}));const next={...r,form_type:type,department_id:$('#fireAttachmentDept').value,inspection_date:$('#fireAttachmentDate').value,responsible_area:$('#fireAttachmentArea').value.trim(),implementer_name:$('#fireAttachmentImplementer').value.trim(),situation_report:$('#fireAttachmentReport')?.value||'',entries,status};if(!next.responsible_area||!next.implementer_name||!next.inspection_date){toast('error','請填寫實施人員、負責區域及日期');return;}if(status==='submitted'&&entries.some(x=>!x.status)){toast('error','請完成全部 9 項檢查結果');return;}try{const out=await api({action:'fire_attachment_save',form_type:type,record:next});current=out.record;records=records.filter(x=>x.id!==current.id).concat(current);toast('saved');editor();}catch(e){toast('error',e.message||'');}}
async function review(decision){const values={action:'fire_attachment_review',form_type:type,id:current.id,updated_at:current.updated_at,manager_name:$('#fireAttachmentManagerName').value.trim(),manager_disposition:$('#fireAttachmentDisposition').value.trim(),manager_signature:$('#fireAttachmentSignature').value.trim(),decision};if(!values.manager_name||!values.manager_disposition||!values.manager_signature){toast('error','請填寫防火管理人姓名、處置情形及簽章');return;}try{const out=await api(values);current=out.record;records=records.filter(x=>x.id!==current.id).concat(current);toast('saved');editor();}catch(e){toast('error',e.message||'');}}
window.renderFireAttachments=async function(formType){type=formType;historyOrigin=false;try{await load();list();}catch(e){$('#content').innerHTML=window.fireFormTabs(type)+`<div class="empty-note">無法讀取附件 ${type}：${safe(e.message)}</div>`;window.bindFireFormTabs();}};
window.openFireAttachmentRecord=async function(formType,id){type=Number(formType);try{await load();const found=records.find(r=>r.id===id&&r.status==='confirmed');if(!found)throw Error('record_unavailable');current=structuredClone(found);historyOrigin=true;editor();}catch(e){$('#content').innerHTML=window.fireFormTabs(4)+`<div class="empty-note">無法開啟簽核紀錄：${safe(e.message)}</div>`;window.bindFireFormTabs();}};
})();
